    match (projective_normal_form(a)?, projective_normal_form(b)?) {
        (Some((na, la)), Some((nb, lb))) => {
            if na == nb {
                Ok(Some(
                    omega_number_theory::scalar::divide(&lb, &la).map_err(FusionError::from)?,
                ))
            } else {
                Ok(None)
            }
        }
        _ => Ok(None),
    }
}

