module::closure_dimension.body:
{
    let Some(first) = generators.first() else {
        return Err(FusionError::ListLength {
            what: "generators",
            expected: 1,
            got: 0,
        });
    };
    let n = first.rows();
    if n == 0 || first.cols() != n {
        return Err(FusionError::NotSquare {
            operation: "group closure (generators must share one square shape)",
            rows: first.rows(),
            cols: first.cols(),
        });
    }
